import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { writeFile } from 'node:fs/promises';
import { readConfig } from './src/config.js';

assert.deepEqual(readConfig({ PORT: '4317', MODE: 'test', APP_LABEL: '  Night Shift  ' }), {
  port: 4317, mode: 'test', label: 'Night Shift',
});
assert.deepEqual(readConfig({ PORT: '0', MODE: 'stage', APP_LABEL: '   ' }), {
  port: 3000, mode: 'dev', label: 'Claudette',
});
assert.deepEqual(readConfig({ PORT: '70000', MODE: 'prod', APP_LABEL: 'Release' }), {
  port: 3000, mode: 'prod', label: 'Release',
});
const cli = spawnSync(process.execPath, ['bin/show-config.js'], {
  encoding: 'utf8',
  env: { ...process.env, PORT: '4317', MODE: 'test', APP_LABEL: '  Night Shift  ' },
});
assert.equal(cli.status, 0, cli.stderr);
assert.equal(cli.stdout, 'Night Shift|test|4317\n');
await writeFile('.passed', 'ok\n');
console.log('ENV MATRIX PASS');
